mapper.select:
SELECT d.*, e.name as director_name, p.name as parent_name, (SELECT COUNT(*) FROM employee emp WHERE emp.department_id = d.id AND emp.delflag = 0 AND emp.employment_status = 1) as employee_count, (SELECT COUNT(*) FROM department child WHERE child.parent_id = d.id AND child.delflag = 0) as children_count FROM department d LEFT JOIN employee e ON d.director_id = e.id AND e.delflag = 0 LEFT JOIN department p ON d.parent_id = p.id AND p.delflag = 0 WHERE d.delflag = 0
AND d.id = #{query.id}
AND d.parent_id = #{query.parentId}
AND d.name LIKE CONCAT('%', #{query.name}, '%')
AND d.dep_no = #{query.depNo}
AND d.director_id = #{query.directorId}
AND d.grade_id = #{query.gradeid}
AND d.fiiale = #{query.fiiale}
AND d.status = #{query.status}
AND d.status = 1
AND (d.name LIKE CONCAT('%', #{query.keyword}, '%') OR d.dep_no LIKE CONCAT('%', #{query.keyword}, '%') OR d.description LIKE CONCAT('%', #{query.keyword}, '%'))
AND d.parent_id = 0
ORDER BY d.sort_order ASC, d.id ASC

SELECT d.*, e.name as director_name, (SELECT COUNT(*) FROM employee emp WHERE emp.department_id = d.id AND emp.delflag = 0 AND emp.employment_status = 1) as employee_count, (SELECT COUNT(*) FROM department child WHERE child.parent_id = d.id AND child.delflag = 0) as children_count FROM department d LEFT JOIN employee e ON d.director_id = e.id AND e.delflag = 0 WHERE d.delflag = 0 AND d.parent_id = #{parentId}
AND d.status = 1
ORDER BY d.sort_order ASC, d.id ASC

SELECT COUNT(*)
FROM employee e
WHERE e.delflag = 0 
    AND e.employment_status = 1


        AND (e.department_id = #{departmentId} 
             OR e.department_id IN (
                 SELECT id FROM department 
                 WHERE parent_id = #{departmentId} AND delflag = 0
             ))


        AND e.department_id = #{departmentId}

SELECT COUNT(*) > 0
FROM department
WHERE dep_no = #{depNo} 
    AND delflag = 0

    AND id != #{excludeId}

SELECT COUNT(*) > 0
FROM department
WHERE name = #{name} 
    AND parent_id = #{parentId}
    AND delflag = 0

    AND id != #{excludeId}

